/* Global Container Freight Tracker: reads data/history.csv, latest.csv and kpi.csv (generated by analyze.py)
   and draws the page. Weekly series with sparse archive history: consecutive periods (at most GAP_DAYS apart)
   are joined by a line, and short runs are drawn as dots. Each chart has its own range picker (all data
   until a year of weekly history has built up, then 3 years); the headline figures and the lane table do
   not depend on it. */
(function () {
  const { num, fmtPct, signCls } = kit;
  const t = (k, v) => i18n.t(k, v);
  const isZh = () => i18n.lang === 'zh';
  const GAP_DAYS = 17;   // a skipped holiday week still joins; archive pairs months apart do not
  const MAX_LANES = 8;   // one colour per selected lane
  const DEFAULT_LANES = ['composite', 'europe', 'med', 'uswc', 'usec'];
  const UPDATE_CMD = 'python -m investdiy.global_track_container_freight';
  const $ = (id) => document.getElementById(id);
  const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
  const pts = (v) => t('pts', { v: kit.fmtNum(v, 2) });
  const pct = (v) => (isFinite(v) ? fmtPct(v) : t('t.none'));

  let D = null;            // loaded data
  const R = {};            // range pickers, one per chart
  let lanes = DEFAULT_LANES.slice();

  const laneName = (r) => (isZh() ? r.name : r.name_en);

  // ---------------- header ----------------
  function drawHeader() {
    const k = D.kpi;
    const set = (id, r) => {
      if (!r) return;
      const c = num(r.chg_1w);
      $(id).textContent = kit.fmtNum(num(r.value), 2);
      $(`${id}-sub`).textContent = isFinite(c) ? t('k.sub', { d: r.date, c: fmtPct(c) }) : t('k.subNone', { d: r.date });
      $(`${id}-sub`).className = 'kpi-sub';
    };
    const scfi = D.latest.get('scfi/composite'), ccfi = D.latest.get('ccfi/composite');
    const eu = D.latest.get('scfis/europe'), us = D.latest.get('scfis/uswc');
    set('k-scfi', scfi); set('k-ccfi', ccfi); set('k-scfis-eu', eu); set('k-scfis-us', us);
    $('asof').textContent = t('common.asof', { d: k.as_of });

    const parts = [];
    if (scfi && ccfi) {
      parts.push(...i18n.rich('take.now', {
        d: scfi.date, scfi: kit.fmtNum(num(scfi.value), 2), c1: pct(num(scfi.chg_1w)),
        ccfi: kit.fmtNum(num(ccfi.value), 2), c2: pct(num(ccfi.chg_1w)),
      }));
    }
    if (eu && us) {
      parts.push(' ', ...i18n.rich('take.scfis', {
        d: eu.date, eu: kit.fmtNum(num(eu.value), 2), c3: pct(num(eu.chg_1w)), us: kit.fmtNum(num(us.value), 2), c4: pct(num(us.chg_1w)),
      }));
    }
    $('take-now').replaceChildren(...parts);
    const n = (D.series.get('ccfi/composite') || []).filter((p) => p.date < k.sse_since).length;
    $('take-cover').replaceChildren(...(k.sse_since ? i18n.rich('take.cover', { since: k.sse_since, n }) : []));
  }

  // ---------------- line chart for weekly series with gaps ----------------
  /** lines: [{key, label, color, rows: [{d, date, v, src}]}] */
  function drawLines(box, card, lines, [s0, e0], H) {
    const tt = kit.tip(card);
    kit.ready(box);
    const shown = lines.map((ln) => ({ ...ln, rows: ln.rows.filter((r) => r.d >= s0 && r.d <= e0) })).filter((ln) => ln.rows.length);
    const all = shown.flatMap((ln) => ln.rows);
    if (!all.length) { kit.fail(box, t('common.failed')); return; }
    const W = Math.max(280, box.clientWidth), m = { t: 10, r: 16, b: 26, l: 52 };
    const x = d3.scaleUtc([s0, e0], [m.l, W - m.r]);
    const y = d3.scaleLinear(d3.extent(all, (r) => r.v), [H - m.b, m.t]).nice();
    const svg = d3.select(box).append('svg').attr('width', '100%').attr('viewBox', `0 0 ${W} ${H}`);
    const ax = svg.append('g').attr('transform', `translate(0,${H - m.b})`)
      .call(d3.axisBottom(x).ticks(Math.max(3, Math.floor(W / 110))).tickSizeOuter(0));
    const ay = svg.append('g').attr('transform', `translate(${m.l},0)`)
      .call(d3.axisLeft(y).ticks(6).tickFormat(d3.format(',')).tickSize(-(W - m.l - m.r)));
    ay.select('.domain').remove();
    kit.axisStyle(ax, ay);

    const near = (a, b) => Math.abs(b.d - a.d) <= GAP_DAYS * 864e5;
    shown.forEach((ln) => {
      const rs = ln.rows;
      // break the line where two periods are more than GAP_DAYS apart
      const segs = [];
      rs.forEach((r, i) => { if (i === 0 || !near(rs[i - 1], r)) segs.push([]); segs[segs.length - 1].push(r); });
      svg.append('g').selectAll('path').data(segs.filter((s) => s.length > 1)).join('path')
        .attr('d', d3.line((r) => x(r.d), (r) => y(r.v)))
        .style('fill', 'none').style('stroke', ln.color).style('stroke-width', 1.8).style('stroke-linejoin', 'round');
      const dots = segs.filter((s) => s.length <= 4 || rs.length <= 80).flat();  // dots on short runs (archive pairs), or everywhere when few
      svg.append('g').selectAll('circle').data(dots).join('circle')
        .attr('cx', (r) => x(r.d)).attr('cy', (r) => y(r.v)).attr('r', 2.6).style('fill', ln.color);
    });

    // tooltip: nearest period across the lines shown, with each line's value on that date
    const dates = [...new Set(all.map((r) => r.date))].sort().map((s) => ({ date: s, d: new Date(s) }));
    const byDate = shown.map((ln) => new Map(ln.rows.map((r) => [r.date, r])));
    const rule = svg.append('line').attr('y1', m.t).attr('y2', H - m.b).style('stroke', 'var(--axis)').style('opacity', 0);
    const bis = d3.bisector((r) => r.d).center;
    svg.append('rect').attr('x', m.l).attr('y', m.t).attr('width', W - m.l - m.r).attr('height', H - m.t - m.b)
      .style('fill', 'transparent')
      .on('mousemove', (event) => {
        const p = dates[bis(dates, x.invert(d3.pointer(event)[0]))];
        rule.attr('x1', x(p.d)).attr('x2', x(p.d)).style('opacity', 1);
        const rows = shown.map((ln, i) => [ln, byDate[i].get(p.date)]).filter(([, r]) => r);
        const archived = rows.some(([, r]) => r.src === 'archive');
        tt.show(event, [
          { text: p.date + (archived ? t('tip.archive') : '') },
          ...rows.map(([ln, r]) => ({ text: `${ln.label} ${pts(r.v)}`, color: ln.color })),
        ]);
      })
      .on('mouseleave', () => { tt.hide(); rule.style('opacity', 0); });
  }

  function legend(host, lines) {
    host.replaceChildren(...lines.map((ln) => {
      const s = el('span'); const i = el('i', 'line'); i.style.background = ln.color;
      s.append(i, ln.label); return s;
    }));
  }

  // ---------------- sections ----------------
  function drawComposite() {
    const S = kit.series();
    const lines = [
      { key: 'scfi', label: t('lg.scfi'), color: S[0], rows: D.series.get('scfi/composite') || [] },
      { key: 'ccfi', label: t('lg.ccfi'), color: S[1], rows: D.series.get('ccfi/composite') || [] },
    ];
    legend($('comp-legend'), lines);
    drawLines($('comp-box'), $('composite'), lines, R.comp.get(), 300);
  }

  function laneColor() {
    const S = kit.series();
    return new Map(lanes.map((k, i) => [k, S[i % S.length]]));
  }

  function drawLanes() {
    const col = laneColor();
    const meta = D.ccfiLanes;
    $('lane-chips').replaceChildren(...meta.map((r) => {
      const b = el('button', 'chip');
      b.type = 'button';
      b.setAttribute('aria-pressed', String(col.has(r.series)));
      const i = el('i'); if (col.has(r.series)) i.style.background = col.get(r.series);
      b.append(i, laneName(r));
      b.addEventListener('click', () => toggleLane(r.series));
      return b;
    }));
    const lines = lanes.map((k) => {
      const r = meta.find((x) => x.series === k);
      return { key: k, label: laneName(r), color: col.get(k), rows: D.series.get(`ccfi/${k}`) || [] };
    });
    drawLines($('lanes-box'), $('lanes'), lines, R.lanes.get(), 300);
    drawLaneTable(col);
  }

  function toggleLane(k) {
    if (lanes.includes(k)) { if (lanes.length > 1) lanes = lanes.filter((x) => x !== k); }
    else lanes = [...lanes, k].slice(-MAX_LANES);
    drawLanes();
  }

  function drawLaneTable(col) {
    $('lane-table').querySelector('tbody').replaceChildren(...D.ccfiLanes.map((r) => {
      const tr = el('tr');
      const td = (text, cls) => { const c = el('td', cls, text); tr.appendChild(c); return c; };
      const name = td(null);
      const sw = el('i'); sw.style.background = col.get(r.series) || 'transparent';
      name.append(sw, laneName(r));
      td(r.date);
      td(kit.fmtNum(num(r.value), 2));
      ['chg_1w', 'chg_4w', 'chg_52w'].forEach((f) => td(pct(num(r[f])), signCls(num(r[f]))));
      td(r.n);
      tr.addEventListener('click', () => toggleLane(r.series));
      return tr;
    }));
  }

  function drawScfis() {
    const S = kit.series();
    const lines = [
      { key: 'europe', label: t('lg.eu'), color: S[0], rows: D.series.get('scfis/europe') || [] },
      { key: 'uswc', label: t('lg.us'), color: S[1], rows: D.series.get('scfis/uswc') || [] },
    ];
    legend($('scfis-legend'), lines);
    drawLines($('scfis-box'), $('scfis'), lines, R.scfis.get(), 260);
  }

  // ---------------- loading ----------------
  function drawAll() {
    if (!D) return;
    drawHeader();
    drawComposite();
    drawLanes();
    drawScfis();
  }

  $('take-now').textContent = t('common.loading');
  kit.sectionNav($('secnav'));
  kit.downloadLinks('data/');

  Promise.all(['kpi', 'latest', 'history'].map((f) => kit.csv(`data/${f}.csv`))).then(([kpi, latest, history]) => {
    const rows = history.map((r) => ({ key: `${r.index}/${r.series}`, date: r.date, d: new Date(r.date), v: num(r.value), src: r.source }));
    D = {
      kpi: kpi[0],
      latest: new Map(latest.map((r) => [`${r.index}/${r.series}`, r])),
      ccfiLanes: latest.filter((r) => r.index === 'ccfi'),
      series: d3.group(rows.sort((a, b) => d3.ascending(a.date, b.date)), (r) => r.key),
    };
    // all data while weekly history is short (earlier years are sparse archive points), 3 years after that
    const since = D.kpi.sse_since ? new Date(D.kpi.sse_since) : null;
    const initial = since && d3.utcYear.offset(since, 1) < new Date() ? '3y' : 'all';
    const picker = (id, keep, draw) => {
      const [min, max] = d3.extent(rows.filter((r) => keep(r.key)), (r) => r.d);
      return kit.rangePicker($(id), { min, max, initial, onChange: draw });
    };
    R.comp = picker('comp-range', (k) => k.endsWith('/composite'), drawComposite);
    R.lanes = picker('lanes-range', (k) => k.startsWith('ccfi/'), drawLanes);
    R.scfis = picker('scfis-range', (k) => k.startsWith('scfis/'), drawScfis);
    kit.markStale($('stale'), D.kpi.as_of, 8);
    drawAll();
    kit.onRedraw(drawAll);
  }).catch((err) => {
    console.error(err);
    const show = () => { $('take-now').textContent = t('loadError', { cmd: UPDATE_CMD }); };
    show();
    i18n.onChange(show);
    ['comp-box', 'lanes-box', 'scfis-box'].forEach((id) => kit.fail($(id)));
  });
})();
